        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Forklift #12",        Location = "Warehouse A", LastInspected = new DateTime(2026, 6, 15) },
            new() { Id = 2, Name = "Conveyor Belt C3",     Location = "Warehouse B", LastInspected = new DateTime(2026, 5, 20) },
            new() { Id = 3, Name = "Hydraulic Press HP-7",  Location = "Plant Floor",  LastInspected = new DateTime(2026, 4, 10) },
            new() { Id = 4, Name = "CNC Lathe L-200",      Location = "Machine Shop", LastInspected = new DateTime(2026, 7, 1)  },
            new() { Id = 5, Name = "Welding Station W-9",   Location = "Plant Floor",  LastInspected = new DateTime(2026, 3, 28) },
            new() { Id = 6, Name = "Air Compressor AC-3",   Location = "Utility Room", LastInspected = new DateTime(2026, 6, 5)  },
            new() { Id = 7, Name = "Overhead Crane OC-1",   Location = "Warehouse A",  LastInspected = new DateTime(2026, 2, 14) },
            new() { Id = 8, Name = "Pallet Jack PJ-44",     Location = "Warehouse B",  LastInspected = new DateTime(2026, 7, 8)  },
        };
    }
}

@page "/inventory"
@using EquipmentApp.Models
@using EquipmentApp.Services
@rendermode InteractiveServer
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistingSubscription;

    private const string PersistenceKey = "inventory-items";

    protected override async Task OnInitializedAsync()
    {
        // Subscribe so we can persist state into the prerendered HTML
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistState);

        // If data was already persisted during prerender, reuse it instead of fetching again
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(PersistenceKey, out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistState()
    {
        ApplicationState.PersistAsJson(PersistenceKey, _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
    }
}

